  DateTime.fromObject({ year: -10, month: 1, day: 1, zone: "utc" }).toISODate() // => "00-10-01-01", expected "-0010-01-01"

APPLY THIS EXACT REPLACEMENT of the whole `padStart` function in /luxon/src/impl/util.js (currently `if (input.toString().length < n) { return ("0".repeat(n) + input).slice(-n); } else { return input.toString(); }`):

  export function padStart(input, n = 2) {
    const isNeg = input < 0;
    let padded;
    if (isNeg) {
      padded = "-" + ("" + -input).padStart(n, "0");
    } else {
      padded = ("" + input).padStart(n, "0");
    }
    return padded;
  }

